#' Confronto partizioni
#'
#' 
#' @param data .
#' @param vars Variabili (almeno due) che codificano partizioni alternative
#'   delle stesse osservazioni. L'Adjusted Rand Index viene calcolato per
#'   ciascuna coppia.
#' @param tuto Se TRUE mostra il pannello con la descrizione metodologica.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$matrix} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$matrix$asDF}
#'
#' \code{as.data.frame(results$matrix)}
#'
#' @export
ari <- function(
    data,
    vars,
    tuto = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ari requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- ariOptions$new(
        vars = vars,
        tuto = tuto)

    analysis <- ariClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

